<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/shared/auth.php';authRequire(false,['ADMIN']);
require_once __DIR__.'/shared-functions.php';
$db=authDb();$message='';$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!authCsrfValid($_POST['csrf_token']??null)){$error='Invalid CSRF token.';}else{
 $type=(string)($_POST['type']??'');$batch=filter_var($_POST['batch']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
 try{if(!$batch||$type!=='EXAM')throw new RuntimeException('Class timetables must be sent directly from the generated preview. This legacy form is only for existing saved exam batches.');
 $db->beginTransaction();$b=acadBatch($db,$type,(int)$batch);if(!$b||$b['status']!=='ACTIVE')throw new RuntimeException('Only active saved batches can be submitted.');
 $hash=acadFingerprint($db,$type,(int)$batch);
 // Rejected submissions cannot be resubmitted. A fresh saved batch is required.
 $column=$type==='CLASS'?'class_batch_id':'exam_batch_id';
 $old=$db->prepare("SELECT approval_id,status FROM academic_approval_requests WHERE $column=? ORDER BY approval_id DESC LIMIT 1 FOR UPDATE");
 $old->execute([$batch]);if($old->fetch())throw new RuntimeException('This saved batch has already been submitted. After rejection, generate and save a NEW batch before requesting approval again.');
 $latest=$db->prepare("SELECT a.approval_id,a.status,a.reviewed_at FROM academic_approval_requests a WHERE a.schedule_type=? AND a.academic_period_id=? AND a.program_id=? ORDER BY a.approval_id DESC LIMIT 1 FOR UPDATE");
 $latest->execute([$type,$b['academic_period_id'],$b['program_id']]);$prev=$latest->fetch();
 if($prev && $prev['status']==='PENDING_REVIEW')throw new RuntimeException('A schedule for this program and academic period is already pending review.');
 if($prev && $prev['status']==='RETURNED'){
   $created=$db->prepare(($type==='CLASS'?'SELECT created_at FROM schedule_batches WHERE batch_id=?':'SELECT created_at FROM exam_batches WHERE exam_batch_id=?'));
   $created->execute([$batch]);$savedAt=$created->fetchColumn();
   if(!$prev['reviewed_at'] || !$savedAt || strtotime((string)$savedAt)<=strtotime((string)$prev['reviewed_at']))throw new RuntimeException('The Academic Office rejected the previous request. Generate and save a new schedule AFTER the rejection before submitting.');
 }

 $check=$db->prepare("SELECT status FROM academic_approval_requests WHERE $column=? AND status IN('PENDING_REVIEW','APPROVED','PUBLISHED') FOR UPDATE");$check->execute([$batch]);if($check->fetch())throw new RuntimeException('This batch already has an open or accepted submission.');
 $rv=$db->prepare("SELECT COALESCE(MAX(revision_no),0)+1 FROM academic_approval_requests WHERE schedule_type=? AND academic_period_id=? AND program_id=?");$rv->execute([$type,$b['academic_period_id'],$b['program_id']]);$revision=(int)$rv->fetchColumn();
 $sql="INSERT INTO academic_approval_requests(schedule_type,$column,academic_period_id,program_id,revision_no,snapshot_hash,submitted_by) VALUES(?,?,?,?,?,?,?)";
 $stmt=$db->prepare($sql);$stmt->execute([$type,$batch,$b['academic_period_id'],$b['program_id'],$revision,$hash,(int)$_SESSION['auth_user_id']]);$id=(int)$db->lastInsertId();
 $q=$db->prepare("INSERT INTO academic_approval_actions(approval_id,actor_id,action_type,remarks) VALUES(?,?,'SUBMITTED','Submitted for institutional review')");$q->execute([$id,(int)$_SESSION['auth_user_id']]);$db->commit();$message='Submission #'.$id.' successfully sent to Academic Office.';
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
 }}
$rows=$db->query("SELECT 'CLASS' kind,b.batch_id id,b.status,p.program_code,ap.academic_year,ap.semester,b.created_at FROM schedule_batches b JOIN programs p ON p.program_id=b.program_id JOIN academic_periods ap ON ap.academic_period_id=b.academic_period_id WHERE b.status='ACTIVE' UNION ALL SELECT 'EXAM' kind,e.exam_batch_id id,e.status,p.program_code,ap.academic_year,ap.semester,e.created_at FROM exam_batches e JOIN programs p ON p.program_id=e.program_id JOIN academic_periods ap ON ap.academic_period_id=e.academic_period_id WHERE e.status='ACTIVE' ORDER BY created_at DESC LIMIT 250")->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Submit to Academic Office</title><link rel="stylesheet" href="assets/office.css"></head><body><main style="max-width:1000px"><a href="../dashboard/dashboard.php">← Back to Scheduler Dashboard</a><h1>Send Schedule Request to Academic Office</h1><p>Class timetables: Generate Schedule → Send to Academic Office directly from the timetable preview. No schedule is saved until Academic Office approves. This page supports existing saved EXAM batches only.</p><?php if($message):?><div class="panel note"><?=acadH($message)?></div><?php endif;if($error):?><div class="panel note error"><?=acadH($error)?></div><?php endif;?><div class="panel"><form method="post"><input type="hidden" name="csrf_token" value="<?=acadH(authCsrf())?>"><label>Timetable type <select name="type" id="kind" required><option value="">Choose type</option><option value="EXAM">Exam</option></select></label><label>Saved active batch <select name="batch" id="batch" required><option value="">Choose a batch</option></select></label><button type="submit">Send Request to Academic Office</button></form></div><div class="panel"><h2>Available saved batches</h2><div class="scroll"><table><tr><th>Type</th><th>Batch</th><th>Program</th><th>Period</th><th>Saved</th></tr><?php foreach($rows as $r):?><tr><td><?=acadH($r['kind'])?></td><td><?=(int)$r['id']?></td><td><?=acadH($r['program_code'])?></td><td><?=acadH($r['academic_year'])?> Sem <?=(int)$r['semester']?></td><td><?=acadH($r['created_at'])?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Approval Requests and Rejection Reasons</h2><div class="scroll"><table><tr><th>Request</th><th>Program</th><th>Type</th><th>Status</th><th>Academic Office remarks</th></tr><?php $history=$db->query("SELECT a.approval_id,a.schedule_type,a.status,a.reviewer_remarks,p.program_code FROM academic_approval_requests a JOIN programs p ON p.program_id=a.program_id ORDER BY a.approval_id DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);foreach($history as $entry):?><tr><td>#<?=(int)$entry['approval_id']?></td><td><?=acadH($entry['program_code'])?></td><td><?=acadH($entry['schedule_type'])?></td><td><?=acadH($entry['status']==='RETURNED'?'REJECTED':$entry['status'])?></td><td><?=acadH($entry['reviewer_remarks']??'—')?></td></tr><?php endforeach;?></table></div></div></main><script type="application/json" id="acadBatchData"><?=json_encode($rows,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="assets/submit.js?v=20" defer></script></body></html>
